INSERT INTO PUBLIC.announcements ("id", "store_id", "title", "description", "icon", "type", "status", "created_at", "updated_at") VALUES (1, 1, '🎉 Estamos muito animados por tê-lo a bordo na nossa plataforma.', 'Olá, Michel Troiano Hayek!<br><br>🎉 Seja muito bem-vindo(a) à Quantso! 🎉 <br><br>Estamos felizes demais por você ter escolhido a gente. Queremos que você se sinta completamente à vontade aqui, afinal, criamos a Quantso pensando em oferecer uma plataforma simples e prática para que você tenha mais agilidade nas suas vendas.<br><br>Sabemos que novos começos podem trazer algumas dúvidas. Mesmo acreditando na simplicidade e intuitividade de nossa plataforma, preparamos um vídeo introdutório para você. Esperamos que ele te ajude a ficar por dentro de todas as possibilidades dentro do nosso app.<br><br>Pronto para iniciar essa nova fase conosco?<br><br>Estamos aqui para o que você precisar.', NULL, 1, 1, '2024-09-10 10:42:40.965733', NULL);
